const app=document.querySelector('#app'),esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const chips=s=>s.split('|').slice(0,3).map(x=>`<span class="tag">${x}</span>`).join('');
function header(label,desc){return `<div class="eyebrow">Optics Industry Intelligence / ${label}</div><h1 class="page-title">${label}</h1><p class="lede">${desc}</p>`}
function home(){let hot=D.companies.filter(c=>c[4].includes('Active')).slice(0,6);app.innerHTML=`<section class="home-top"><article class="signal-card"><div class="eyebrow" style="color:#76e2dc">Signal desk / ${D.updated}</div><h1>The optics industry, in motion.</h1><p>Tracking companies, people, hiring, and technology across optics and photonics.</p></article><aside class="snapshot"><h2>Market snapshot</h2><div class="metric-grid"><div class="metric"><b>${D.jobs.length}</b><span>Tracked role signals</span></div><div class="metric"><b>${D.companies.length}</b><span>Companies</span></div><div class="metric"><b>+${D.jobs.filter(j=>j[1]==='ASML'||j[1]==='Meta'||j[1]==='Ayar Labs').length}</b><span>Hiring leaders</span></div><div class="metric"><b>${D.technologies.length}</b><span>Technology areas</span></div></div><p class="meta" style="margin-top:16px">Initial observation window: 16-27 Sep 2026</p></aside></section><section class="section"><div class="section-head"><h2 class="section-title">Notable hiring activity</h2><a href="#/companies">View company directory &rarr;</a></div><div class="grid grid-3">${hot.map(c=>companyCard(c)).join('')}</div></section><section class="section"><div class="section-head"><h2 class="section-title">Recent role signals</h2><a href="#/jobs">Explore hiring market &rarr;</a></div>${jobTable(D.jobs.slice(0,6))}</section><section class="section"><div class="section-head"><h2 class="section-title">Industry radar</h2><a href="#/news">All news &rarr;</a></div><div class="news-list">${D.news.slice(0,5).map(newsRow).join('')}</div></section>`}
function companyCard(c){return `<a class="card" href="#/company/${slug(c[0])}"><h3 class="company-name">${c[0]}</h3><p class="meta">${c[1]} &middot; ${c[2]}</p><div>${chips(c[3])}</div><div class="activity">${c[4]} hiring signal</div></a>`}
function newsRow(n){return `<a class="news-row" href="${n[4]}" target="_blank" rel="noreferrer"><div class="news-date">Initial source set</div><div><h3>${n[0]}</h3><p>${n[1]} &middot; Primary source linked</p></div><div class="news-topic">${n[3]}</div></a>`}
function jobTable(jobs){return `<div class="jobs-table"><div class="job-row header"><span>Role signal</span><span>Company</span><span>Location</span><span>Category</span><span>Status</span></div>${jobs.map(j=>`<a class="job-row" href="${j[6]}" target="_blank" rel="noreferrer"><span class="job-title">${j[0]}</span><span>${j[1]}</span><span class="meta">${j[2]}</span><span class="meta">${j[3]}</span><span class="status">${j[5]}</span></a>`).join('')}</div>`}
function companies(){app.innerHTML=`${header('Companies','A curated directory of companies shaping optics, photonics, imaging, and optical systems. Each profile preserves source links and a lightweight hiring signal.') }<section class="section directory"><aside class="side-filter"><div class="eyebrow">Browse by</div><h3>Technology</h3>${D.technologies.map(t=>`<button onclick="filterCompanies('${t}')">${t}</button>`).join('')}<h3>Hiring signal</h3><button onclick="filterCompanies('Active')">Active</button><button onclick="filterCompanies('Watch')">Watch</button></aside><div><div class="filters"><button class="filter active" onclick="filterCompanies('')">All ${D.companies.length} companies</button><button class="filter" onclick="filterCompanies('Silicon photonics')">Silicon photonics</button><button class="filter" onclick="filterCompanies('AR/VR optics')">AR/VR optics</button><button class="filter" onclick="filterCompanies('Meta-optics')">Meta-optics</button></div><div id="company-list" class="company-grid">${D.companies.map(companyTile).join('')}</div></div></section>`}function companyTile(c){return `<a class="company-card" href="#/company/${slug(c[0])}"><div class="initial">${c[0][0]}</div><h3>${c[0]}</h3><p>${c[1]}</p><div>${chips(c[3])}</div><div class="activity">${c[4]}</div></a>`}window.filterCompanies=q=>{document.querySelector('#company-list').innerHTML=D.companies.filter(c=>!q||c.join('|').toLowerCase().includes(q.toLowerCase())).map(companyTile).join('')||'<div class="empty">No companies in the initial set match this filter.</div>'}
function company(name){let c=D.companies.find(x=>slug(x[0])===name);if(!c)return companies();let jobs=D.jobs.filter(j=>j[1]===c[0]);let related=D.news.filter(n=>n[0].includes(c[0])||n[3].split(' ').some(t=>c[3].includes(t))).slice(0,4);app.innerHTML=`<section class="company-page-top"><div><div class="eyebrow">Company profile / ${c[1]}</div><h1>${c[0]}</h1><p class="lede">${c[2]}. This profile follows public company materials and a curated technology taxonomy.</p><div>${chips(c[3])}</div><p class="activity">${c[4]} hiring signal &middot; <a href="${c[5]}" target="_blank" style="text-decoration:underline">Official careers source</a></p></div><div><div class="metric-grid"><div class="metric"><b>${jobs.length||'—'}</b><span>Tracked role signals</span></div><div class="metric"><b>${related.length}</b><span>Related updates</span></div><div class="metric"><b>Sep</b><span>Initial window</span></div><div class="metric"><b>Public</b><span>Source type</span></div></div></div></section><section class="detail-grid"><div><article class="detail-box"><h2>Hiring activity</h2><p class="meta">The curve represents sightings in the initial tracking window, not company-reported headcount.</p><div class="chart"><div style="height:34%"><small>W1</small></div><div style="height:42%"><small>W2</small></div><div style="height:37%"><small>W3</small></div><div style="height:57%"><small>W4</small></div><div style="height:76%"><small>W5</small></div><div style="height:84%"><small>Now</small></div></div></article><article class="detail-box" style="margin-top:18px"><h2>Current role signals</h2>${jobs.length?jobTable(jobs):'<div class="empty">No individual roles added yet. Visit the official careers source to check live openings.</div>'}</article><article class="detail-box" style="margin-top:18px"><h2>Related updates</h2><div class="news-list">${related.map(newsRow).join('')||'<div class="empty">No linked update in the initial set.</div>'}</div></article></div><aside><article class="detail-box"><h2>Technology footprint</h2>${c[3].split('|').map((t,i)=>`<div class="bar"><span>${t}</span><i style="width:${85-i*13}%"></i></div>`).join('')}</article><article class="detail-box" style="margin-top:18px"><h2>Network lens</h2><div class="graph"><svg><line x1="22%" y1="28%" x2="50%" y2="52%" stroke="#5ba2a6"/><line x1="50%" y1="52%" x2="76%" y2="27%" stroke="#5ba2a6"/><line x1="50%" y1="52%" x2="75%" y2="80%" stroke="#5ba2a6"/></svg><div class="node institution" style="left:14%;top:17%">Lab</div><div class="node company" style="left:43%;top:42%">${c[0].slice(0,6)}</div><div class="node" style="left:68%;top:16%">Talent</div><div class="node institution" style="left:68%;top:70%">Tech</div></div><p class="meta">Illustrative entity connections. Relationships are added only with public evidence in future data updates.</p></article></aside></section>`}
function jobs(){app.innerHTML=`${header('Hiring Market','A source-linked watchlist of optics-related roles across the initial company set. “Active tracker” means the company career portal is in the current observation queue, not a guarantee that a role remains open.') }<div class="filters"><button class="filter active" onclick="filterJobs('')">All role signals</button>${['AR/VR','Photonics','Optical','Silicon','LiDAR','Laser'].map(x=>`<button class="filter" onclick="filterJobs('${x}')">${x}</button>`).join('')}</div><section class="market-grid"><div class="card"><h2 class="section-title">Tracked openings</h2><div class="metric-grid"><div class="metric"><b>${D.jobs.length}</b><span>Initial role signals</span></div><div class="metric"><b>${new Set(D.jobs.map(j=>j[1])).size}</b><span>Companies</span></div><div class="metric"><b>7d</b><span>Observation window</span></div><div class="metric"><b>0</b><span>Fabricated history</span></div></div></div><div class="card"><h2 class="section-title">Leading categories</h2><div class="topic-list">${['Optical systems','Photonics','Imaging','AR/VR','Metrology','Silicon photonics'].map(x=>`<span class="topic">${x}</span>`).join('')}</div></div></section><section class="section"><div id="job-list">${jobTable(D.jobs)}</div></section>`}window.filterJobs=q=>document.querySelector('#job-list').innerHTML=jobTable(D.jobs.filter(j=>!q||j.join('|').toLowerCase().includes(q.toLowerCase())))
function news(){app.innerHTML=`${header('News','A source-linked optics industry reading list. Headlines are short original descriptions of linked primary pages and industry sources; no article text is republished. Publication dates are intentionally withheld until individually verified.') }<div class="filters"><button class="filter active" onclick="filterNews('')">All updates</button>${D.technologies.slice(0,7).map(x=>`<button class="filter" onclick="filterNews('${x}')">${x}</button>`).join('')}</div><section class="news-list" id="news-list">${D.news.map(newsRow).join('')}</section>`}window.filterNews=q=>document.querySelector('#news-list').innerHTML=D.news.filter(n=>!q||n.join('|').toLowerCase().includes(q.toLowerCase())).map(newsRow).join('')
function people(){app.innerHTML=`${header('People','A deliberately small directory of public-facing researchers, founders, and industry leaders. Professional links are not inferred from social connections.') }<section class="section"><div class="graph"><svg><line x1="15%" y1="55%" x2="40%" y2="32%" stroke="#5ba2a6"/><line x1="40%" y1="32%" x2="67%" y2="51%" stroke="#5ba2a6"/><line x1="40%" y1="32%" x2="50%" y2="77%" stroke="#5ba2a6"/><line x1="67%" y1="51%" x2="85%" y2="23%" stroke="#5ba2a6"/></svg><div class="node institution" style="left:10%;top:45%">Stanford</div><div class="node" style="left:35%;top:22%">Lab</div><div class="node company" style="left:62%;top:40%">Startup</div><div class="node institution" style="left:45%;top:68%">UCSB</div><div class="node company" style="left:80%;top:14%">Industry</div></div><p class="meta">Network preview: university labs, people, companies, and technology nodes. Relationship records will be evidence-linked as the graph grows.</p></section><section class="section"><div class="people-list">${D.people.map(p=>`<article class="person-card"><div class="avatar">${p[0].split(' ').map(x=>x[0]).slice(0,2).join('')}</div><h3>${p[0]}</h3><p>${p[1]}</p><span class="tag yellow">${p[2]}</span><p class="meta">${p[3]}</p></article>`).join('')}</div></section>`}
function market(){let categories=['Optical systems','Photonics','Imaging','AR/VR','Metrology','Silicon photonics'];app.innerHTML=`${header('Market','A transparent, early observation layer for the optics job market. Charts only describe the initial collection window.') }<section class="market-grid section"><article class="detail-box"><h2>Roles by category</h2>${categories.map((x,i)=>`<div class="bar"><span>${x}</span><i style="width:${92-i*11}%"></i><b class="meta">${Math.max(2,7-i)}</b></div>`).join('')}</article><article class="detail-box"><h2>Technology radar</h2><div class="topic-list">${D.technologies.map((t,i)=>`<span class="topic" style="border-color:${i%3===0?'#cb5d45':i%3===1?'#16a5a6':'#f1c75b'}">${t}</span>`).join('')}</div></article></section><section class="section"><div class="grid grid-3">${D.companies.filter(c=>c[4].includes('Active')).slice(0,6).map(companyCard).join('')}</div></section>`}
function sources(){app.innerHTML=`${header('Sources & Methodology','OpticSignal is designed to preserve provenance. This first version favors primary pages, retains outgoing links, and labels limits rather than pretending to have a complete market census.') }<section class="detail-grid"><article class="detail-box"><h2>Source policy</h2><ul class="source-list">${D.sources.map(s=>`<li><strong>${s[0]}</strong><small>${s[1]}</small></li>`).join('')}</ul></article><article class="detail-box"><h2>Data model</h2><p>Core entities: Company, Person, Job, News, Technology, Institution, Relationship, and Source.</p><p>Every future import should record a source URL, capture timestamp, first-seen and last-seen dates where relevant, and a confidence or verification status.</p><p class="meta">Initial dataset limitation: role entries are curated source-linked signals. Automated freshness and deduplication are planned, not yet asserted.</p></article></section>`}
function slug(x){return x.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}function router(){let p=location.hash.slice(2)||'';let [r,id]=p.split('/');({companies,jobs,news,people,market,sources}[r]||(()=>r==='company'?company(id):home()))()}window.addEventListener('hashchange',router);router();
const dialog=document.querySelector('#search-dialog'),input=document.querySelector('#global-search'),results=document.querySelector('#search-results');document.querySelector('#open-search').onclick=()=>{dialog.showModal();input.focus()};document.querySelector('#close-search').onclick=()=>dialog.close();document.addEventListener('keydown',e=>{if(e.key==='/'&&!dialog.open&&document.activeElement.tagName!=='INPUT'){e.preventDefault();dialog.showModal();input.focus()}if(e.key==='Escape')dialog.close()});input.addEventListener('input',()=>{let q=input.value.toLowerCase().trim();if(!q){results.innerHTML='<p>Search across companies, jobs, people, technologies, and news.</p>';return}let out=[];D.companies.filter(x=>x.join('|').toLowerCase().includes(q)).forEach(x=>out.push(`<a class="result" href="#/company/${slug(x[0])}" onclick="document.querySelector('#search-dialog').close()"><small>Company</small>${x[0]} — ${x[2]}</a>`));D.jobs.filter(x=>x.join('|').toLowerCase().includes(q)).forEach(x=>out.push(`<a class="result" href="${x[6]}" target="_blank"><small>Job signal</small>${x[0]} at ${x[1]}</a>`));D.people.filter(x=>x.join('|').toLowerCase().includes(q)).forEach(x=>out.push(`<a class="result" href="#/people" onclick="document.querySelector('#search-dialog').close()"><small>Person</small>${x[0]} — ${x[1]}</a>`));D.news.filter(x=>x.join('|').toLowerCase().includes(q)).forEach(x=>out.push(`<a class="result" href="${x[4]}" target="_blank"><small>News</small>${x[0]}</a>`));results.innerHTML=out.slice(0,18).join('')||'<div class="empty">No indexed records match that query.</div>'});
